    "\t\t\t\telse\r\n",
    "\t\t\t\t\tself._custom_data[key] = value\r\n",
    "\t\t\t\tend\r\n",
    "\t\t\tend\r\n",
    "\t\tend\r\n",
    "\r\n",
    "\t\tself._weapon_update = template and template.update\r\n",
    "\t\tself._weapon_wield = template and template.on_wield\r\n",
    "\t\tself._weapon_unwield = template and template.on_unwield\r\n",
